// `repr()` for Python `str` and `bytes` values -- this is what `print()` shows
// when handed a bytes object.

const TAB = 0x09;
const NEWLINE = 0x0a;
const CARRIAGE_RETURN = 0x0d;
const SPACE = 0x20;
const DOUBLE_QUOTE = 0x22;
const SINGLE_QUOTE = 0x27;
const BACKSLASH = 0x5c;
const DELETE = 0x7f;

// Escapes a code point the way CPython does when it cannot render it literally:
// \xhh below U+0100, \uhhhh below U+10000, \Uhhhhhhhh above.
export function escapeCodePoint(point) {
  if (point <= 0xff) return `\\x${point.toString(16).padStart(2, '0')}`;
  if (point <= 0xffff) return `\\u${point.toString(16).padStart(4, '0')}`;
  return `\\U${point.toString(16).padStart(8, '0')}`;
}

// Python prefers a single-quoted repr, switching to double quotes only when the
// value contains a single quote but no double quote.
function chooseQuote(hasSingle, hasDouble) {
  return hasSingle && !hasDouble ? DOUBLE_QUOTE : SINGLE_QUOTE;
}

// Only \t, \n, \r, the backslash and the active delimiter get short escapes;
// every other unprintable value falls through to \xhh. Notably \x0b and \x0c
// are *not* rendered as \v and \f.
function escapeByte(value, quote) {
  if (value === BACKSLASH) return '\\\\';
  if (value === TAB) return '\\t';
  if (value === NEWLINE) return '\\n';
  if (value === CARRIAGE_RETURN) return '\\r';
  if (value === quote) return `\\${String.fromCharCode(quote)}`;
  if (value >= SPACE && value < DELETE) return String.fromCharCode(value);
  return escapeCodePoint(value);
}

// repr() of a Python `bytes` object, given its values as a list of numbers.
export function bytesRepr(byteList) {
  const quote = chooseQuote(
    byteList.includes(SINGLE_QUOTE),
    byteList.includes(DOUBLE_QUOTE),
  );
  const delimiter = String.fromCharCode(quote);
  let body = '';
  for (const value of byteList) body += escapeByte(value, quote);
  return `b${delimiter}${body}${delimiter}`;
}

// repr() of a Python `str`. Callers here only ever pass characters drawn from
// the ASCII range, which is the domain where this matches CPython exactly.
export function strRepr(text) {
  const points = toArrayOfCharCodes(text);
  const quote = chooseQuote(
    points.includes(SINGLE_QUOTE),
    points.includes(DOUBLE_QUOTE),
  );
  const delimiter = String.fromCharCode(quote);
  let body = '';
  for (const value of points) body += escapeByte(value, quote);
  return `${delimiter}${body}${delimiter}`;
}

function toArrayOfCharCodes(text) {
  const codes = [];
  for (let index = 0; index < text.length; index += 1) {
    codes.push(text.charCodeAt(index));
  }
  return codes;
}

