// Python exceptions reproduced closely enough that the interpreter's traceback
// and exit status can be replayed byte for byte.

import { escapeCodePoint } from './pyrepr.mjs';

// The source line the original script dies on, rendered the way Python 3.11+
// renders it (with the caret run under the failing sub-expression).
const SCRIPT_FRAME = [
  '  File "test7.py", line 10, in <module>',
  '    decoded = base58.b58decode(args.b)  # 解码Base58字符串',
  '              ^^^^^^^^^^^^^^^^^^^^^^^^',
];

export class PyError extends Error {
  // `frames` are the library frames printed between the script frame and the
  // final exception line, innermost last.
  constructor(pyName, pyMessage, frames = []) {
    super(`${pyName}: ${pyMessage}`);
    this.name = pyName;
    this.pyName = pyName;
    this.pyMessage = pyMessage;
    this.frames = frames;
  }
}

export class PyValueError extends PyError {
  constructor(message, frames) {
    super('ValueError', message, frames);
  }
}

export class PyUnicodeEncodeError extends PyError {
  // CPython collapses a run of consecutive unencodable characters into a single
  // report, and only names the character when the run is exactly one long.
  constructor(encoding, codePoint, start, end, frames) {
    const location = start === end
      ? `character '${escapeCodePoint(codePoint)}' in position ${start}`
      : `characters in position ${start}-${end}`;
    super(
      'UnicodeEncodeError',
      `'${encoding}' codec can't encode ${location}: ordinal not in range(128)`,
      frames,
    );
  }
}

export function formatTraceback(error) {
  const lines = ['Traceback (most recent call last):', ...SCRIPT_FRAME];
  for (const frame of error.frames) {
    lines.push(`  File "base58/__init__.py", line ${frame.line}, in ${frame.name}`);
  }
  lines.push(`${error.pyName}: ${error.pyMessage}`);
  return lines.join('\n');
}

// The frozen build prints the traceback, then its own bootstrap notice, and
// leaves with status 1.
export function reportFatal(error) {
  process.stderr.write(`${formatTraceback(error)}\n`);
  process.stderr.write(
    `[PYI-${process.pid}:ERROR] Failed to execute script 'test7' due to unhandled exception!\n`,
  );
  process.exit(1);
}

