// `str.encode(...)` for the two codecs this program uses. Results are plain
// lists of numeric byte values so the rest of the pipeline stays arithmetic.

import { toCodePoints } from './pytext.mjs';
import { PyUnicodeEncodeError } from './pyerrors.mjs';

const MAX_ASCII = 0x7f;

// `str.encode()` -- UTF-8, the default codec.
export function encodeUtf8(text) {
  const byteList = [];
  for (const point of toCodePoints(text)) {
    if (point < 0x80) {
      byteList.push(point);
    } else if (point < 0x800) {
      byteList.push(0xc0 | (point >> 6), 0x80 | (point & 0x3f));
    } else if (point < 0x10000) {
      byteList.push(
        0xe0 | (point >> 12),
        0x80 | ((point >> 6) & 0x3f),
        0x80 | (point & 0x3f),
      );
    } else {
      byteList.push(
        0xf0 | (point >> 18),
        0x80 | ((point >> 12) & 0x3f),
        0x80 | ((point >> 6) & 0x3f),
        0x80 | (point & 0x3f),
      );
    }
  }
  return byteList;
}

// `str.encode('ascii')`. Positions in the raised error are code-point indices,
// and a run of consecutive unencodable characters is reported as one range.
export function encodeAscii(text, frames) {
  const points = toCodePoints(text);
  const start = points.findIndex((point) => point > MAX_ASCII);
  if (start !== -1) {
    let end = start;
    while (end + 1 < points.length && points[end + 1] > MAX_ASCII) end += 1;
    throw new PyUnicodeEncodeError('ascii', points[start], start, end, frames);
  }
  return points;
}

