// Exact radix conversion for arbitrarily large values held as digit lists.
//
// The value is never materialised as a single number, so there is no precision
// ceiling: each input digit is folded into the accumulator with schoolbook
// multiply-and-carry, exactly like Python's arbitrary-precision integers.

// Converts `digits` (big-endian, base `fromBase`) to big-endian base `toBase`.
// Leading zeros are dropped, so a zero value converts to an empty list -- which
// is what Python's minimal integer encodings produce too.
export function convertBase(digits, fromBase, toBase) {
  const result = []; // little-endian while we accumulate
  for (const digit of digits) {
    // result = result * fromBase + digit
    let carry = digit;
    for (let index = 0; index < result.length; index += 1) {
      carry += result[index] * fromBase;
      result[index] = carry % toBase;
      carry = (carry - result[index]) / toBase;
    }
    while (carry > 0) {
      const remainder = carry % toBase;
      result.push(remainder);
      carry = (carry - remainder) / toBase;
    }
  }
  return result.reverse();
}

// Both conversions used here keep intermediates at 57 * 256 + 255 = 14847 or
// 255 * 58 + 57 = 14847, far inside exact integer arithmetic.
export function maxIntermediate(fromBase, toBase) {
  return (toBase - 1) * fromBase + (fromBase - 1);
}

