// Base58 codec matching the behaviour of Python's `base58` package.
//
// Both functions speak in Python types: they take/return byte values as plain
// lists of numbers, mirroring `bytes` in and `bytes` out.

import { convertBase } from './basecodec.mjs';
import { rstrip } from './pytext.mjs';
import { encodeAscii } from './utf8.mjs';
import { PyValueError } from './pyerrors.mjs';
import { strRepr } from './pyrepr.mjs';

export const BITCOIN_ALPHABET =
  '123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz';

// Frames the library contributes to a traceback when it raises.
const SCRUB_INPUT_FRAMES = [
  { line: 118, name: 'b58decode' },
  { line: 30, name: 'scrub_input' },
];
const DECODE_INT_FRAMES = [
  { line: 124, name: 'b58decode' },
  { line: 104, name: 'b58decode_int' },
];

function alphabetIndex(alphabet) {
  const index = new Map();
  for (let position = 0; position < alphabet.length; position += 1) {
    index.set(alphabet.charCodeAt(position), position);
  }
  return index;
}

// `b58encode(bytes)`. Leading zero bytes are not part of the numeric value, so
// they are carried across as literal leading '1' characters.
export function b58encode(byteList, alphabet = BITCOIN_ALPHABET) {
  let zeros = 0;
  while (zeros < byteList.length && byteList[zeros] === 0) zeros += 1;

  const digits = convertBase(byteList.slice(zeros), 256, 58);
  const text = alphabet[0].repeat(zeros) + digits.map((d) => alphabet[d]).join('');

  // The Python function hands back `bytes`; the alphabet is ASCII-only.
  const encoded = [];
  for (let index = 0; index < text.length; index += 1) {
    encoded.push(text.charCodeAt(index));
  }
  return encoded;
}

// `b58decode(str)`. The library right-strips whitespace *before* the ASCII
// check, so a trailing full-width space is fine while a leading one is not.
export function b58decode(value, alphabet = BITCOIN_ALPHABET) {
  const trimmed = rstrip(value);
  const asciiBytes = encodeAscii(trimmed, SCRUB_INPUT_FRAMES);

  const one = alphabet.charCodeAt(0);
  let zeros = 0;
  while (zeros < asciiBytes.length && asciiBytes[zeros] === one) zeros += 1;

  const index = alphabetIndex(alphabet);
  const digits = asciiBytes.slice(zeros).map((byteValue) => {
    const digit = index.get(byteValue);
    if (digit === undefined) {
      const character = strRepr(String.fromCharCode(byteValue));
      throw new PyValueError(`Invalid character ${character}`, DECODE_INT_FRAMES);
    }
    return digit;
  });

  const decoded = convertBase(digits, 58, 256);
  return [...new Array(zeros).fill(0), ...decoded];
}

