import { ArgumentParser } from './lib/argparse.mjs';
import { encodeUtf8 } from './lib/utf8.mjs';
import { b58encode, b58decode } from './lib/base58.mjs';
import { bytesRepr } from './lib/pyrepr.mjs';
import { PyError, reportFatal } from './lib/pyerrors.mjs';

const parser = new ArgumentParser({ prog: 'test7_executable' });
parser.addArgument('--a', { required: true });
parser.addArgument('--b', { required: true });
const args = parser.parseArgs(process.argv.slice(2));

try {
  const encoded = b58encode(encodeUtf8(args.a)); // 编码字符串
  const decoded = b58decode(args.b); // 解码Base58字符串
  console.log(bytesRepr(encoded));
  console.log(bytesRepr(decoded));
} catch (error) {
  // Both values are computed before either is printed, so a bad --b keeps the
  // encode result off stdout -- same as the Python script.
  if (error instanceof PyError) reportFatal(error);
  throw error;
}

