// Emulates the parts of `linecache` and the Python 3.11+ traceback renderer
// that decide whether a frame shows its source line and caret run.
//
// The frozen build carries no source, so the interpreter resolves "test7.py"
// against the *current working directory*: run it from beside the script and the
// traceback gains two extra lines, run it from anywhere else and it does not.

import { readFileSync } from 'node:fs';
import { toCodePoints } from './pytext.mjs';

// `linecache.getline` -- returns '' for a missing file or an out-of-range line,
// and keeps the trailing newline, which the offset arithmetic below depends on.
export function getline(filename, lineno) {
  let text;
  try {
    text = readFileSync(filename, 'utf8');
  } catch {
    return '';
  }
  const lines = text.replace(/\r\n/g, '\n').split('\n');
  if (lineno < 1 || lineno > lines.length) return '';
  return lineno === lines.length ? lines[lineno - 1] : `${lines[lineno - 1]}\n`;
}

function utf8Width(point) {
  if (point < 0x80) return 1;
  if (point < 0x800) return 2;
  if (point < 0x10000) return 3;
  return 4;
}

// `StackSummary._byte_offset_to_character_offset`: how many characters the first
// `byteOffset` bytes of the UTF-8 encoding decode to, truncation included.
function byteOffsetToCharOffset(text, byteOffset) {
  let bytes = 0;
  let characters = 0;
  for (const point of toCodePoints(text)) {
    const width = utf8Width(point);
    if (bytes + width > byteOffset) {
      // A partially included character decodes to one replacement character.
      return bytes < byteOffset ? characters + 1 : characters;
    }
    bytes += width;
    characters += 1;
  }
  return characters;
}

function countLeadingWhitespace(rawLine) {
  return rawLine.length - rawLine.replace(/^\s+/, '').length;
}

// Renders one traceback frame. `colOffset`/`endColOffset` are byte columns taken
// from the code object -- they survive freezing even when the source does not,
// which is why the caret run is always in step with the source line.
export function formatFrame(filename, lineno, funcName, colOffset, endColOffset) {
  const lines = [`  File "${filename}", line ${lineno}, in ${funcName}`];

  const rawLine = getline(filename, lineno);
  const strippedLine = rawLine.trim();
  if (strippedLine === '') return lines;

  lines.push(`    ${strippedLine}`);

  if (colOffset !== undefined && endColOffset !== undefined) {
    const stripped = countLeadingWhitespace(rawLine);
    const start = byteOffsetToCharOffset(rawLine, colOffset);
    const end = byteOffsetToCharOffset(rawLine, endColOffset);
    const indent = Math.max(0, 4 + start - stripped);
    const carets = Math.max(0, end - start);
    lines.push(' '.repeat(indent) + '^'.repeat(carets));
  }
  return lines;
}

