// `str.rstrip()` with no argument.
export function rstrip(text) {
  const points = toCodePoints(text);
  let end = points.length;
  while (end > 0 && isSpaceCodePoint(points[end - 1])) end -= 1;
  return end === points.length ? text : fromCodePoints(points.slice(0, end));
}

// `str.lstrip()` with no argument.
export function lstrip(text) {
  const points = toCodePoints(text);
  let start = 0;
  while (start < points.length && isSpaceCodePoint(points[start])) start += 1;
  return start === 0 ? text : fromCodePoints(points.slice(start));
}

// `str.strip()` with no argument. Differs from JS `trim()` at the edges: U+001C
// through U+001F count as whitespace here, U+FEFF does not.
export function strip(text) {
  return lstrip(rstrip(text));
