input.content:
#!/usr/bin/env bash
# Randomised differential fuzz: random --a payloads and random --b inputs
# (valid base58, near-miss base58, whitespace-padded, unicode, junk).
PY=/workspace/dataset/test7_executable
JS="node /output/test7.mjs"
N=${1:-400}
pass=0; fail=0
norm() { sed -E 's/^\[PYI-[0-9]+:ERROR\]/[PYI-PID:ERROR]/'; }

cmp_case() {
  local po jo pe je pr jr
  po=$("$PY" --a "$1" --b "$2" 2>/tmp/fpe); pr=$?
  jo=$($JS --a "$1" --b "$2" 2>/tmp/fje); jr=$?
  pe=$(norm </tmp/fpe); je=$(norm </tmp/fje)
  if [[ "$po" == "$jo" && "$pe" == "$je" && "$pr" == "$jr" ]]; then
    pass=$((pass+1))
  else
    fail=$((fail+1))
    echo "### MISMATCH a=$(printf '%q' "$1") b=$(printf '%q' "$2")"
    echo "py rc=$pr out=$(printf '%q' "$po") err=$(printf '%q' "$pe")"
    echo "js rc=$jr out=$(printf '%q' "$jo") err=$(printf '%q' "$je")"
  fi
}

B58='123456789ABCDEFGHJKLMNPQRSTUVWXYZabcdefghijkmnopqrstuvwxyz'
JUNK='0OIl+/=-_.!~$&*()[]{}<>?,;:@#%^|`"'"'"'\ '
WS=(' ' $'\t' $'\n' $'\r' $'\x0b' $'\x0c' $'\x1c' $'\x1f' $'\xc2\xa0' $'\xe3\x80\x80' $'\xe2\x80\x8a')
UNI=('中' '国' '汉' '字' 'é' 'Ω' '😀' '🎉' 'ü' 'Ł' $'​' $'᠎')

rnd_b58() { local n=$1 s=''; for ((i=0;i<n;i++)); do s+=${B58:$((RANDOM%58)):1}; done; printf '%s' "$s"; }
rnd_ascii() { head -c "$1" /dev/urandom | tr -dc '\40-\176' ; }
rnd_junk() { local n=$1 s=''; for ((i=0;i<n;i++)); do s+=${JUNK:$((RANDOM%${#JUNK})):1}; done; printf '%s' "$s"; }

for ((k=0;k<N;k++)); do
  # --- random --a payload ---
  case $((RANDOM%5)) in
    0) a=$(rnd_ascii $((RANDOM%40+1)));;
    1) a=$(rnd_b58 $((RANDOM%60+1)));;
    2) a=""; for ((i=0;i<RANDOM%8+1;i++)); do a+=${UNI[$((RANDOM%${#UNI[@]}))]}; done;;
    3) a=$(rnd_junk $((RANDOM%20+1)));;
    4) a=$(rnd_ascii $((RANDOM%15+1)))${UNI[$((RANDOM%${#UNI[@]}))]}$(rnd_ascii $((RANDOM%15+1)));;
  esac
  # --- random --b input ---
  case $((RANDOM%7)) in
    0) b=$(rnd_b58 $((RANDOM%70+1)));;
    1) b=$(printf '1%.0s' $(seq 1 $((RANDOM%5+1))))$(rnd_b58 $((RANDOM%20+1)));;
    2) b=$(rnd_b58 $((RANDOM%20+1)))${WS[$((RANDOM%${#WS[@]}))]};;
    3) b=$(rnd_b58 $((RANDOM%15+1)))$(rnd_junk 1)$(rnd_b58 $((RANDOM%10)));;
    4) b=$(rnd_b58 $((RANDOM%10)))${UNI[$((RANDOM%${#UNI[@]}))]}$(rnd_b58 $((RANDOM%10)));;
    5) b=$(rnd_junk $((RANDOM%6+1)));;
    6) b=$(rnd_b58 $((RANDOM%120+40)));;
  esac
  cmp_case "$a" "$b"
done
echo "pass=$pass fail=$fail"

